 raw=C.github('/actions/artifacts/'+str(ARTIFACT)+'/zip')
 C.require(C.digest(raw)=={'bytes':2974740,'sha256':ZIP_SHA},'Actual raw archive digest')
 with zipfile.ZipFile(io.BytesIO(raw)) as z:
  infos=z.infolist()
